// Compartido por entrada, storyboard, planos y sonido. Sin evidencia ni URLs privadas.
function validarPresentacion(value) {
  if (value === undefined || value === null) return null;
  const obj = x => x && typeof x === 'object' && !Array.isArray(x);
  if (!obj(value) || value.version !== 1 || !['completo', 'partes'].includes(value.presencia) ||
      !Object.hasOwn(value, 'avatar') || !Object.hasOwn(value, 'voz') ||
      Object.keys(value).some(k => !['version', 'presencia', 'avatar', 'voz'].includes(k))) throw new Error('Presentación inválida');
  for (const kind of ['avatar', 'voz']) {
    const m = value[kind];
    if (m === null) continue;
    if (!obj(m) || !['propio', 'catalogo'].includes(m.tipo) ||
        ![m.id, m.recurso_id].every(x => typeof x === 'string' && /^[\w-]{1,160}$/.test(x)) ||
        Object.keys(m).some(k => !['recurso_id', 'proveedor', 'id', 'tipo'].includes(k))) throw new Error('Recurso inválido');
    if (m.proveedor === 'simulada') throw new Error('Recurso de demostración');
    if (kind === 'avatar' ? m.proveedor !== 'heygen' :
      !(m.proveedor === 'gemini' && m.tipo === 'catalogo' || ['heygen', 'elevenlabs'].includes(m.proveedor) && m.tipo === 'propio')) throw new Error('Proveedor incompatible');
  }
  return value;
}
function planosPresentacion(planos, value) {
  const p = validarPresentacion(value);
  const narrados = planos.filter(x => String(x.texto_narrado || '').trim());
  if (!narrados.length && (p?.avatar || p?.voz)) throw new Error('La presentación requiere narración');
  const result = planos.map(x => {
    const habla = !!String(x.texto_narrado || '').trim();
    const avatar = !!p?.avatar && habla && (p.presencia === 'completo' || x.usa_avatar === true || x.tipo === 'avatar');
    if (x.tipo === 'avatar' && !avatar) throw new Error('Plano avatar sin presentación autorizada');
    return { ...x, ...(p ? { usa_avatar: avatar, presentacion: p } : {}), ...(avatar ? { tipo: 'avatar' } : {}) };
  });
  if (p?.avatar && p.presencia === 'partes') {
    const n = result.filter(x => x.usa_avatar).length;
    if (!n || narrados.length > 1 && n === narrados.length) throw new Error('Storyboard: elige solo algunas escenas con usa_avatar');
  }
  return result;
}
function costoVozPresentacion(texto, value, aj) {
  const voz = value?.voz;
  const tarifa = voz?.proveedor === 'heygen' ? aj.costoVozHeygenCaracterUsd : voz?.proveedor === 'elevenlabs' ? aj.costoVozElevenCaracterUsd : null;
  const costo = tarifa === null ? Number(aj.costoVozUsdPorPlano) : String(texto || '').replace(/\[[^\]]*\]|<[^>]*>/g, '').length * Number(tarifa);
  if (!Number.isFinite(costo) || costo < 0) throw new Error('Configura la tarifa de voz');
  return costo;
}

const e = $('Inicio').first().json, v = $('Video de presentación').first().json, aj = $('Leer ajustes').first().json;
const presentacion = validarPresentacion(JSON.parse(v.presentacion || 'null'));
if (!v.video_id && e.presentacion) throw new Error('Falta el video persistido');
if (!presentacion || !presentacion.avatar && !presentacion.voz) return [{json:{consultar:false}}];
if (!v.cooper_orden_id || !v.dueno_email) throw new Error('Presentación sin orden autorizada');
const bloqueo = e.bloqueo || (presentacion.avatar && !aj.allowAvatar ? 'avatar_apagado' : !aj.allowVoz ? 'voz_apagada' :
  ['medios','montaje'].includes(e.control) && (!aj.allowMontaje || !aj.allowDrive) ? 'produccion_pausada' : '');
return [{json:{consultar:true, consulta:{version:'cooper-v1', tipo:'presentacion', orden_id:v.cooper_orden_id,
  video_id:v.video_id, dueno_email:v.dueno_email, presentacion, bloqueo}}}];

const secret = String($env.COOPER_WEBHOOK_SECRET || '');
if (secret.length < 32) throw new Error('Falta COOPER_WEBHOOK_SECRET');
const cuerpo = JSON.stringify($('Consulta de presentación').first().json.consulta), timestamp = String(Date.now());
const firma = require('crypto').createHmac('sha256', secret).update(timestamp + '.' + cuerpo).digest('hex');
return [{ json: { cuerpo, timestamp, firma: 'sha256=' + firma } }];

// Política pura de transporte. No envía solicitudes ni conserva errores de proveedores.
function evaluarRespuestaFiable(r, intento, ahora = Date.now(), azar = Math.random()) {
  if (!Number.isInteger(intento) || intento < 1 || intento > 4) throw new Error('Intento de transporte inválido');
  const recibido = Number(r?.statusCode || r?.error?.statusCode || r?.error?.httpCode || 0);
  const codigo = Number.isInteger(recibido) ? recibido : 0;
  if (codigo >= 200 && codigo < 300) return { reintentar: false, esperaSegundos: 0, respuesta: r.body, codigo };
  const transitorio = [408, 425, 429].includes(codigo) || (codigo >= 500 && codigo <= 599) || (!codigo && !!r?.error);
  if (!transitorio) throw new Error('Respuesta HTTP no recuperable; revisar la incidencia sin reenviar la operación');
  if (intento === 4) throw new Error('Transporte agotado tras cuatro intentos seguros; requiere conciliación');
  const headers = r.headers || r.error?.headers || {};
  const raw = Object.entries(headers).find(([k]) => k.toLowerCase() === 'retry-after')?.[1];
  let retryAfter = 0;
  if (raw !== undefined) {
    const texto = String(raw).trim();
    if (/^\d+(?:\.\d+)?$/.test(texto)) retryAfter = Math.ceil(Number(texto));
    else {
      // Date.parse admite basura como "-1" o fechas abreviadas: aceptar solo
      // IMF-fixdate y exigir que la fecha y el día de semana sean coherentes.
      const instante = Date.parse(texto);
      if (!/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \d{4} \d{2}:\d{2}:\d{2} GMT$/.test(texto) || !Number.isFinite(instante) || new Date(instante).toUTCString() !== texto) {
        throw new Error('Retry-After inválido; detener antes de incumplir la cuota');
      }
      retryAfter = Math.max(0, Math.ceil((instante - ahora) / 1000));
    }
    if (!Number.isFinite(retryAfter)) throw new Error('Retry-After inválido; detener antes de incumplir la cuota');
    // El callback firmado caduca: no esperar indefinidamente ni anticipar Retry-After.
    if (retryAfter > 60) throw new Error('Retry-After excede el presupuesto; reanudar tras conciliación');
  }
  const base = [2, 8, 32][intento - 1];
  const jitter = Math.min(2, Math.max(0, Math.floor(Number(azar) * 3) || 0));
  return { reintentar: true, esperaSegundos: Math.max(base + jitter, retryAfter), respuesta: null, codigo };
}

function clavePublicacionFiable(video, tipo, red) {
  if (!video || !tipo || !red) throw new Error('Publicación sin identidad estable');
  return 'publicacion:v1:' + require('crypto').createHash('sha256').update(JSON.stringify([String(video), String(tipo), String(red)])).digest('hex');
}

function publicacionYaReservada(video, tipo, red, publicaciones, reservas) {
  const clave = clavePublicacionFiable(video, tipo, red);
  return reservas.some(r => r.evento === clave) || publicaciones.some(p => p.video_id === video && p.tipo === tipo && String(p.plataformas || '').split(',').includes(red));
}

function elegirReservasPublicacion(pedidos, propias, reservas) {
  const vistas = new Set();
  return pedidos.filter(p => {
    const clave = p.clave_publicacion;
    if (!clave || vistas.has(clave)) return false;
    vistas.add(clave);
    const mia = propias.filter(r => r.evento === clave);
    const todas = reservas.filter(r => r.evento === clave);
    if (mia.length !== 1 || !todas.length || [...mia, ...todas].some(r => !Number.isSafeInteger(Number(r.id)) || Number(r.id) <= 0)) {
      throw new Error('No se pudo verificar la reserva de publicación; no reenviar');
    }
    const id = Number(mia[0].id);
    if (!todas.some(r => Number(r.id) === id)) throw new Error('La reserva aún no es visible; no reenviar');
    return id === Math.min(...todas.map(r => Number(r.id)));
  });
}

return [{json:evaluarRespuestaFiable($json,1)}];

